#include <iostream>

bool isPrime(int n) {
    for (int d = 2; d * d <= n; ++d) if (n % d == 0) return false;
    return n > 1;
}

int main() {
    std::cout << (isPrime(29) ? "prime" : "composite") << "\n";
    return 0;
}

