class Account {
public:
    explicit Account(int start) : balance(start) {}
    void withdraw(int amount) { if (amount <= balance) balance -= amount; }
    int get() const { return balance; }
private:
    int balance;
};

int main() {
    Account a(100);
    a.withdraw(200);
    std::cout << a.get() << "\n";
    return 0;
}

